import {score,server,complete,rate,validate} from './domain.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),id=()=>crypto.randomUUID(),today=()=>new Date().toLocaleDateString('sv-SE');
let db,state={version:1,matches:[],opponents:[]},page='record',mid=null,gi=0,draft={},editing=null,filter='',statScope='match',drill=null,ready=false;
const labels={subject:'关键一板归属',phase:'记录环节',spin:'发球旋转',side:'侧旋方向',length:'发球长短',landing:'球台落点',timing:'击球时期',position:'身体位置',distance:'身体距离',height:'击球高度',hand:'正反手',technique:'使用技术',rally:'回合板数',initiative:'先上手方',outcome:'得失分方式',result:'球的结果',cause:'可能原因',custom:'自定义标签',notes:'本分备注'};
const choices={subject:['我方','对方'],phase:['发球','接发球','终结一板'],spin:['下旋','上旋','侧下旋','侧上旋','纯侧旋','不转','不确定'],side:['左侧旋','右侧旋','不确定'],length:['短球','半出台','长球'],timing:['上升期','高点期','下降期'],position:['身前','身侧','身后'],distance:['太近','合适','太远'],height:['高于网','接近网高','低于网'],hand:['正手','反手'],technique:['搓','摆短','劈长','挑','拧','拉','攻','挡','推','削'],initiative:['我方','对方','不确定'],outcome:['我方主动得分','对方失误','对方主动得分','我方失误'],result:['下网','出界','漏球','擦网','擦边'],cause:['判断旋转错误','脚步不到位','击球过早','击球过晚','重心不稳','还原慢','战术选择','主动失误','被迫失误','不确定']};
const match=()=>state.matches.find(m=>m.id===mid), opponent=m=>state.opponents.find(o=>o.id===m?.opponentId), game=()=>match()?.games[gi];
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500);}
async function init(){try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open('pingpong-lab',1);r.onupgradeneeded=()=>r.result.createObjectStore('data');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});const saved=await new Promise((resolve,reject)=>{const r=db.transaction('data').objectStore('data').get('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});if(saved)state=validate(saved);ready=true;mid=state.matches[0]?.id||null;render();}catch(e){$('#app').innerHTML='<div class="card">无法读取本地数据，请勿清理浏览器数据。错误：'+esc(e.message)+'</div>';}}
async function persist(next){await new Promise((resolve,reject)=>{const tx=db.transaction('data','readwrite');tx.objectStore('data').put(next,'state');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('保存中断'));});}
async function change(fn){const previous=structuredClone(state);try{fn();validate(state);await persist(state);render();return true;}catch(e){state=previous;toast('保存失败：'+e.message+'。请导出备份后检查设备空间。');render();return false;}}
function chips(k,value=draft[k]){return `<div class="field"><label>${labels[k]}</label><div class="chips">${choices[k].map(v=>`<button type="button" data-tag="${k}" data-value="${v}" class="${value===v?'active':''}">${v}</button>`).join('')}</div></div>`;}
function tagForm(d=draft){return `<div class="grid">${chips('subject',d.subject)}${chips('phase',d.phase)}</div><div class="grid">${chips('hand',d.hand)}${chips('technique',d.technique)}</div><div class="grid">${chips('outcome',d.outcome)}${chips('cause',d.cause)}</div><details ${editing?'open':''}><summary>更多细节 · 发球、落点与击球点</summary><div class="grid"><div>${chips('spin',d.spin)}${chips('side',d.side)}${chips('length',d.length)}</div><div class="field"><label>球台落点 · 接球者视角</label><div class="tablegrid">${['近网','中台','底线'].flatMap(depth=>['反手','中路','正手'].map(side=>`${side}·${depth}`)).map(v=>`<button type="button" data-tag="landing" data-value="${v}" class="${d.landing===v?'active':''}">${v}</button>`).join('')}</div><p class="help">与上方“记录环节”对应。左手对手也按正手 / 反手记录。</p></div></div><div class="grid">${['timing','position','distance','height','initiative','result'].map(k=>chips(k,d[k])).join('')}<div><label>回合板数 · 发球为第 1 板</label><input type="number" min="1" max="999" data-input="rally" value="${esc(d.rally)}" placeholder="没数清可留空"></div><div><label>自定义标签 · 用逗号分隔</label><input data-input="custom" value="${esc(d.custom)}" placeholder="例如：掉腕，反手衔接"></div></div></details><label>本分备注</label><textarea data-input="notes" placeholder="记录一个观察，留给下一次训练…">${esc(d.notes)}</textarea>`;}
function render(){if(!ready)return;const titles={record:['逐分记录','把每一分，变成下一次进步。'],matches:['比赛档案','每一次交手，都值得留下。'],opponents:['对手笔记','了解对手，也了解自己的选择。'],stats:['复盘统计','从记录中，找到训练的方向。'],backup:['数据与备份','把积累留在自己手里。']};$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">◒ <span>PingPong</span> Lab<small>乒乓球 · 复盘笔记</small></div><nav class="nav">${[['record','◎','逐分记录'],['matches','▤','比赛档案'],['opponents','♙','对手笔记'],['stats','▥','复盘统计'],['backup','↗','数据与备份']].map(([p,i,t])=>`<button data-page="${p}" class="${page===p?'active':''}">${i}　${t}</button>`).join('')}</nav><div class="sidefoot">一分一记，日积月累。<br>个人训练记录 / V1<br>数据仅保存在当前设备</div></aside><main class="main"><header class="top"><div><div class="eyebrow">PINGPONG LAB / ${page.toUpperCase()}</div><h1>${titles[page][0]}</h1><small>${titles[page][1]}</small></div><span class="pill">● 本地自动保存</span></header>${({record:recordPage,matches:matchesPage,opponents:opponentsPage,stats:statsPage,backup:backupPage}[page])()}</main></div>`;}
function recordPage(){const m=match(),g=game();if(!m||!g)return `<div class="card empty"><h2>从第一场比赛开始</h2><p>建一场比赛，边看球边记录。<br>每分只需点击得分或失分，细节可以随时补充。</p><button class="primary" data-action="newMatch">＋ 新建比赛</button></div>`;const s=score(g.points),finished=complete(g.points);return `<div class="row between" style="margin-bottom:18px"><div class="row"><select id="matchSelect" style="width:auto">${state.matches.map(x=>`<option value="${x.id}" ${x.id===mid?'selected':''}>${esc(x.date)} · vs ${esc(opponent(x)?.name)}</option>`).join('')}</select><select id="gameSelect" style="width:auto">${m.games.map((x,i)=>`<option value="${i}" ${i===gi?'selected':''}>第 ${i+1} 局</option>`).join('')}</select></div><button data-action="newMatch">＋ 新比赛</button></div><div class="layout"><section><div class="card scoreboard"><div class="row between"><span>第 ${gi+1} 局 <small>／ 11 分制单打</small></span><small>${finished?'本局已结束':'第 '+(g.points.length+1)+' 分'}</small></div><div class="score"><div><small>我方</small><strong>${s[0]}</strong></div><i>:</i><div><small>${esc(opponent(m)?.name)}</small><strong>${s[1]}</strong></div></div><div class="row between"><small>下一分：${server(g.points,g.first)==='self'?'我方':'对方'}发球</small><div class="row"><button data-action="first">首发：${g.first==='self'?'我方':'对方'} ⇄</button><button data-action="undo" ${g.points.length?'':'disabled'}>↶ 撤销</button></div></div><div class="scorebuttons"><button data-action="win" ${finished?'disabled':''}>＋ 我得分</button><button data-action="lose" ${finished?'disabled':''}>＋ 我失分</button></div>${finished?'<button class="gap" data-action="nextGame">开始下一局 →</button>':'<p class="help" style="color:#bdcec1;margin:12px 0 0">先选标签，再点得失分保存。也可以先记分，稍后补充。</p>'}</div><div class="card"><div class="sectiontitle"><h2>这一分，发生了什么？</h2><button data-action="clearDraft">清空标签</button></div><p class="help">以下均可不填。默认描述关键一板，点击已选标签可取消。</p>${tagForm()}<div class="gap"><label>本分发球方修正（可选）</label><select id="serverOverride"><option value="">按规则自动推算</option><option value="self" ${draft.serverOverride==='self'?'selected':''}>我方</option><option value="opponent" ${draft.serverOverride==='opponent'?'selected':''}>对方</option></select></div></div></section><aside><div class="card"><div class="sectiontitle"><h2>本局记录</h2><span class="badge">${g.points.length} 分</span></div><div class="history">${g.points.length?g.points.map((p,i)=>pointRow(p,i,g)).reverse().join(''):'<div class="empty">还没有记录<br>第一分，从这里开始。</div>'}</div></div><div class="card"><h3>对手观察</h3><p class="help">${esc(opponent(m)?.notes||'还没有对手笔记。记录常用发球、强弱项和应对策略。')}</p><button data-action="editOpponent" data-id="${m.opponentId}">编辑对手笔记</button></div><div class="card"><h3>当场观察与赛后总结</h3><p class="help">${esc(m.notes||'这场发现了什么？下次想练什么？')}</p><button data-action="summary">填写本场总结</button></div></aside></div>`;}
function pointRow(p,i,g,context='edit'){const s=score(g.points.slice(0,i+1));return `<div class="record"><span class="dot ${p.winner==='self'?'':'loss'}">${i+1}</span><div class="body"><b>${s[0]} : ${s[1]}</b> <small>${p.winner==='self'?'得分':'失分'} · ${(p.serverOverride||server(g.points.slice(0,i),g.first))==='self'?'我发':'对发'}</small><p>${esc(Object.values(p.tags).filter(Boolean).join(' · ')||'未添加标签')}</p></div>${context==='edit'?`<button data-action="editPoint" data-id="${p.id}">编辑</button>`:''}</div>`;}
function matchesPage(){return `<div class="row between" style="margin-bottom:20px"><span>${state.matches.length} 场比赛</span><button class="primary" data-action="newMatch">＋ 新建比赛</button></div>${state.matches.length?state.matches.map(m=>`<div class="card matchitem"><div class="row between"><div><small>${esc(m.date)}</small><h2 style="margin:8px 0">我方 vs ${esc(opponent(m)?.name)}</h2><p class="muted">${m.games.map((g,i)=>`第${i+1}局 ${score(g.points).join(':')}${complete(g.points)?'':'（进行中）'}`).join('　')}</p></div><div class="row"><button data-action="openMatch" data-id="${m.id}">继续记录 →</button><button class="danger" data-action="deleteMatch" data-id="${m.id}">删除</button></div></div><p class="help">${esc(m.notes||'暂无本场总结')}</p></div>`).join(''):'<div class="card empty">还没有比赛，创建第一场吧。</div>'}`;}
function opponentsPage(){return `<div class="row between" style="margin-bottom:20px"><span>${state.opponents.length} 位对手</span><button class="primary" data-action="newOpponent">＋ 新建对手</button></div><div class="grid">${state.opponents.map(o=>`<div class="card"><div class="row between"><h2>${esc(o.name)}</h2><button data-action="editOpponent" data-id="${o.id}">编辑</button></div><span class="badge">${state.matches.filter(m=>m.opponentId===o.id).length} 次交手</span><p class="help gap" style="white-space:pre-wrap">${esc(o.notes||'添加打法、发球习惯与应对策略。')}</p></div>`).join('')||'<div class="card empty">对手档案可在新建比赛时一起创建。</div>'}</div>`;}
function allPoints(){let ms=statScope==='match'?(match()?[match()]:[]):state.matches;if(filter)ms=ms.filter(m=>m.opponentId===filter);return ms.flatMap(m=>m.games.flatMap((g,j)=>(statScope==='game'&&m.id===mid&&j!==gi?[]:g.points.map((p,i)=>({...p,server:p.serverOverride||server(g.points.slice(0,i),g.first),matchId:m.id,gameIndex:j,index:i,date:m.date}))))).filter(p=>statScope!=='game'||p.matchId===mid);}
function metric(title,ps){const r=rate(ps);return `<div class="metric"><small>${title}</small><strong>${r.total?r.percent+'%':'—'}</strong><small>${r.won} 得分 / ${r.total} 分</small></div>`;}
function groupValue(p,key){if(key==='rally'){const n=+p.tags.rally;return !n?'':n<=2?'1–2 板':n<=4?'3–4 板':n<=8?'5–8 板':'9+ 板';}return p.tags[key]||'';}
function statsPage(){const ps=allPoints();return `<div class="row" style="margin-bottom:20px"><select id="scope" style="width:auto"><option value="game" ${statScope==='game'?'selected':''}>当前局</option><option value="match" ${statScope==='match'?'selected':''}>当前比赛</option><option value="all" ${statScope==='all'?'selected':''}>所有比赛</option></select><select id="opponentFilter" style="width:auto"><option value="">全部对手</option>${state.opponents.map(o=>`<option value="${o.id}" ${filter===o.id?'selected':''}>${esc(o.name)}</option>`).join('')}</select><span class="muted">当前：${match()?esc(match().date)+' · '+esc(opponent(match())?.name):'无比赛'}</span></div><div class="stats">${metric('总得分率',ps)}${metric('发球轮得分率',ps.filter(p=>p.server==='self'))}${metric('接发球轮得分率',ps.filter(p=>p.server==='opponent'))}</div><p class="help">只统计已填写的标签。每行显示“得分 / 样本数”，小样本仅供参考；点击分类查看原始记录。</p><div class="grid">${['spin','landing','rally','hand','technique','cause'].map(key=>{const vals=[...new Set(ps.map(p=>groupValue(p,key)).filter(Boolean))];return `<div class="card"><h2>${key==='cause'?'失分原因分布':labels[key]+'表现'}</h2>${vals.length?vals.map(v=>{const subset=ps.filter(p=>groupValue(p,key)===v&&(key!=='cause'||p.winner==='opponent'));const r=rate(subset);return `<div class="barrow"><button data-action="drill" data-key="${key}" data-value="${esc(v)}">${esc(v)}</button><div class="bar"><span style="width:${key==='cause'?Math.round(r.total/Math.max(1,ps.filter(p=>p.winner==='opponent').length)*100):r.percent}%"></span></div><span>${key==='cause'?r.total+' 次失分':r.won+' / '+r.total+' · '+r.percent+'%'}</span></div>`}).join(''):'<p class="empty">填写标签后，这里会出现统计。</p>'}</div>`}).join('')}</div>${drill?`<div class="card"><div class="sectiontitle"><h2>${esc(drill.value)} · 原始记录</h2><button data-action="closeDrill">收起</button></div>${ps.filter(p=>groupValue(p,drill.key)===drill.value&&(drill.key!=='cause'||p.winner==='opponent')).map(p=>`<div class="record"><div class="body">${esc(p.date)} · 第${p.gameIndex+1}局 · 第${p.index+1}分 · ${p.winner==='self'?'得分':'失分'}<p>${esc(Object.values(p.tags).filter(Boolean).join(' · '))}</p></div><button data-action="jump" data-id="${p.matchId}" data-game="${p.gameIndex}" data-point="${p.id}">查看</button></div>`).join('')}</div>`:''}`;}
function backupPage(){return `<div class="card"><h2>完整备份与恢复</h2><p class="help">记录保存在当前浏览器的本地数据库。清理网站数据、卸载或更换设备可能丢失记录，请定期导出。手机和平板之间可以手动导入备份，不会自动同步。</p><div class="row"><button class="primary" data-action="export">↓ 导出完整 JSON 备份</button><button data-action="import">↑ 从备份恢复</button><button data-action="csv">导出逐分 CSV 表格</button></div><input id="importFile" type="file" accept=".json,application/json" hidden><p class="help gap">恢复会替换当前数据；操作前会先导出当前数据。CSV 用于查看与分析，恢复请使用 JSON。</p></div><div class="card"><h2>在安卓平板上使用</h2><p class="help">用平板浏览器打开应用地址，在浏览器菜单中选择“安装应用”或“添加到主屏幕”。首次联网加载完成后，再测试断网启动。首次使用和私有站点登录需要联网。</p><p id="offlineState" class="help">${'serviceWorker' in navigator?'应用会自动准备离线资源；实际离线启动请在平板验证。':'当前环境不支持离线安装。'}</p><p class="help">记录无需视频，也不上传比赛数据。应用更新和安装资源需要网络。</p></div>`;}
function modal(html){$('#modal').innerHTML=html;$('#modal').showModal();}
function newMatch(){modal(`<h2>新建一场比赛</h2><form id="newMatchForm"><div class="grid"><div><label>日期</label><input name="date" type="date" value="${today()}" required></div><div><label>已有对手</label><select name="opponent"><option value="">新增对手</option>${state.opponents.map(o=>`<option value="${o.id}">${esc(o.name)}</option>`).join('')}</select></div></div><label class="gap">新对手姓名 / 昵称（选择已有对手时可留空）</label><input name="name" maxlength="80" placeholder="例如：老张"><label class="gap">第一局首发</label><select name="first"><option value="self">我方</option><option value="opponent">对方</option></select><div class="row gap"><button class="primary">开始记录</button><button type="button" data-action="close">取消</button></div></form>`);}
function editOpponent(oid){const o=state.opponents.find(x=>x.id===oid);modal(`<h2>${o?'编辑':'新建'}对手笔记</h2><form id="opponentForm" data-id="${o?.id||''}"><label>姓名 / 昵称</label><input name="name" value="${esc(o?.name)}" required maxlength="80"><label class="gap">基本特点、技战术习惯与应对办法</label><textarea name="notes" style="min-height:230px" placeholder="持拍：左/右手，直/横板，胶皮\n打法：\n常用发球与接发球：\n正反手强弱项、常打落点：\n有效的应对策略：">${esc(o?.notes)}</textarea><div class="row gap"><button class="primary">保存笔记</button><button type="button" data-action="close">取消</button></div></form>`);}
function editPoint(pid){const p=game().points.find(x=>x.id===pid);editing=pid;draft={...p.tags,serverOverride:p.serverOverride||''};modal(`<h2>编辑这一分</h2><form id="pointForm"><div class="grid field"><div><label>得失分</label><select name="winner"><option value="self" ${p.winner==='self'?'selected':''}>我得分</option><option value="opponent" ${p.winner==='opponent'?'selected':''}>我失分</option></select></div><div><label>发球方修正</label><select id="serverOverride"><option value="">自动推算</option><option value="self" ${draft.serverOverride==='self'?'selected':''}>我方</option><option value="opponent" ${draft.serverOverride==='opponent'?'selected':''}>对方</option></select></div></div>${tagForm()}<div class="row gap"><button class="primary">保存修改</button><button type="button" data-action="close">取消</button><button type="button" class="danger" data-action="deletePoint" data-id="${pid}">删除这一分</button></div></form>`);}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function backup(){download('PingPong-Lab-'+today()+'-'+Date.now()+'.json',JSON.stringify(state,null,2));}
function csv(){const rows=[['日期','对手','局','分','我方分前比分','对方分前比分','发球方','得失分',...Object.values(labels)]];for(const m of state.matches)for(const [j,g]of m.games.entries())for(const [i,p]of g.points.entries()){rows.push([m.date,opponent(m)?.name,j+1,i+1,...score(g.points.slice(0,i)),(p.serverOverride||server(g.points.slice(0,i),g.first))==='self'?'我方':'对方',p.winner==='self'?'得分':'失分',...Object.keys(labels).map(k=>p.tags[k]||'')]);}download('PingPong-Lab-'+today()+'.csv','\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8');}
document.addEventListener('input',e=>{if(e.target.dataset.input)draft[e.target.dataset.input]=e.target.value;});
document.addEventListener('change',async e=>{const t=e.target;if(t.id==='matchSelect'){mid=t.value;gi=0;draft={};render();}if(t.id==='gameSelect'){gi=+t.value;draft={};render();}if(t.id==='serverOverride')draft.serverOverride=t.value;if(t.id==='scope'){statScope=t.value;drill=null;render();}if(t.id==='opponentFilter'){filter=t.value;drill=null;render();}if(t.id==='importFile'&&t.files[0]){try{if(t.files[0].size>20*1024*1024)throw Error('备份超过 20MB');const imported=validate(JSON.parse(await t.files[0].text()));if(!confirm(`恢复 ${imported.matches.length} 场比赛、${imported.opponents.length} 位对手？将替换当前数据，先自动导出当前备份。`))return;backup();if(await change(()=>{state=imported;mid=state.matches[0]?.id||null;gi=0;draft={};})){toast('备份已恢复');}}catch(err){toast('导入失败：'+err.message);}}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){page=b.dataset.page;render();return;}if(b.dataset.tag){const k=b.dataset.tag,v=b.dataset.value;draft[k]=draft[k]===v?'':v;b.closest('.field').querySelectorAll('[data-tag]').forEach(x=>x.classList.toggle('active',draft[k]===x.dataset.value));return;}const a=b.dataset.action;if(!a)return;if(a==='close'){$('#modal').close();editing=null;draft={};render();}if(a==='newMatch')newMatch();if(a==='newOpponent')editOpponent();if(a==='editOpponent')editOpponent(b.dataset.id);if(a==='clearDraft'){draft={};render();}if(a==='openMatch'){mid=b.dataset.id;gi=0;draft={};page='record';render();}if(a==='win'||a==='lose'){if(complete(game().points))return;if(draft.rally&&(!Number.isInteger(+draft.rally)||+draft.rally<1||+draft.rally>999)){toast('回合板数请填 1–999 的整数');return;}const {serverOverride,...tags}=draft;const won=a==='win';if(tags.outcome&&((won&&['对方主动得分','我方失误'].includes(tags.outcome))||(!won&&['我方主动得分','对方失误'].includes(tags.outcome)))){toast('得失分方式与按钮不一致，请修改标签');return;}b.disabled=true;if(await change(()=>game().points.push({id:id(),winner:won?'self':'opponent',serverOverride:serverOverride||'',tags:{...tags}}))){draft={};render();toast('已记录并保存');}}if(a==='undo'&&game().points.length){if(confirm('撤销本局最后一分？'))await change(()=>game().points.pop());}if(a==='first'){if(!game().points.length||confirm('修改首发会重新计算本局自动发球方，手动修正不变。继续？'))await change(()=>game().first=game().first==='self'?'opponent':'self');}if(a==='nextGame'){await change(()=>{const m=match();if(gi===m.games.length-1)m.games.push({first:game().first==='self'?'opponent':'self',points:[]});gi++;draft={};});}if(a==='editPoint')editPoint(b.dataset.id);if(a==='deletePoint'&&confirm('删除这一分？后续比分与发球方会重新计算。')){if(await change(()=>game().points=game().points.filter(p=>p.id!==b.dataset.id))){$('#modal').close();editing=null;draft={};render();}}if(a==='deleteMatch'&&confirm('永久删除这场比赛？建议先导出备份。'))await change(()=>{state.matches=state.matches.filter(m=>m.id!==b.dataset.id);mid=state.matches[0]?.id||null;gi=0;});if(a==='summary')modal(`<h2>当场观察与赛后总结</h2><form id="summaryForm"><textarea name="notes" style="min-height:260px" placeholder="对手当场特点：\n做得好的地方：\n主要问题：\n下次训练重点：">${esc(match().notes)}</textarea><div class="row gap"><button class="primary">保存总结</button><button type="button" data-action="close">取消</button></div></form>`);if(a==='export')backup();if(a==='csv')csv();if(a==='import')$('#importFile').click();if(a==='drill'){drill={key:b.dataset.key,value:b.dataset.value};render();$('.main').lastElementChild?.scrollIntoView({behavior:'smooth',block:'end'});}if(a==='closeDrill'){drill=null;render();}if(a==='jump'){mid=b.dataset.id;gi=+b.dataset.game;page='record';render();editPoint(b.dataset.point);}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,v=new FormData(f);let ok=false;if(f.id==='newMatchForm'){if(!v.get('opponent')&&!String(v.get('name')).trim()){toast('请填写对手昵称或选择已有对手');return;}ok=await change(()=>{let oid=v.get('opponent');if(!oid){oid=id();state.opponents.push({id:oid,name:String(v.get('name')).trim(),notes:''});}mid=id();gi=0;draft={};state.matches.unshift({id:mid,opponentId:oid,date:v.get('date'),notes:'',games:[{first:v.get('first'),points:[]}]});page='record';});}if(f.id==='opponentForm')ok=await change(()=>{const o=state.opponents.find(x=>x.id===f.dataset.id);if(o){o.name=String(v.get('name')).trim();o.notes=v.get('notes');}else state.opponents.push({id:id(),name:String(v.get('name')).trim(),notes:v.get('notes')});});if(f.id==='summaryForm')ok=await change(()=>match().notes=v.get('notes'));if(f.id==='pointForm'){if(draft.rally&&(!Number.isInteger(+draft.rally)||+draft.rally<1||+draft.rally>999)){toast('回合板数请填 1–999 的整数');return;}ok=await change(()=>{const p=game().points.find(x=>x.id===editing);const {serverOverride,...tags}=draft;p.winner=v.get('winner');p.serverOverride=serverOverride||'';p.tags={...tags};});}if(ok){$('#modal').close();editing=null;draft={};render();toast('已保存');}});
$('#modal').addEventListener('cancel',()=>{editing=null;draft={};render();});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
init();
